import {filterGames,playedSets,rosterFor} from './services.js';
import {escapeHTML as esc} from './config.js';
const rate=(n,d)=>d?n/d*100:null;
const pct=v=>v===null?'−':v.toFixed(1)+'%';
export function setterStats(games,setterId){
 const result={attempts:0,points:0,over:0,under:0,success:0,fail:0,unplayable:0,linked:0,linkedPoints:0,untracked:0,games:0,sets:0,targets:[]},targets=new Map();
 for(const game of games){let included=false;for(const {s,i} of playedSets(game)){const roster=rosterFor(game,i);if(!roster.some(p=>p.playerId===setterId))continue;const raw=s.players[setterId]||{},links=s.settingLinks?.[setterId]||{};const observed=['AL','AM','AN','AO','AP','AQ'].some(k=>raw[k]>0)||Object.values(links).some(a=>a.length);if(!observed)continue;included=true;result.sets++;result.over+=raw.AL||0;result.under+=raw.AM||0;result.points+=raw.AO||0;result.success+=raw.AN||0;result.fail+=raw.AP||0;result.unplayable+=raw.AQ||0;
 const typed=Object.hasOwn(links,'AL')||Object.hasOwn(links,'AM');for(const key of (typed?['AL','AM']:['AN','AO','AP'])){const tracked=(links[key]||[]).slice(0,raw[key]||0);result.untracked+=Math.max(0,(raw[key]||0)-tracked.length);for(const id of tracked){const p=roster.find(p=>p.playerId===id)||game.roster.find(p=>p.playerId===id);if(!targets.has(id))targets.set(id,{id,name:p?.name||'미상 선수',position:p?.position||'',attempts:0,points:0,success:0,fail:0,outcomeTrials:0});const row=targets.get(id);row.attempts++;if(!typed){row.outcomeTrials++;row[key==='AO'?'points':key==='AN'?'success':'fail']++;}result.linked++;if(key==='AO')result.linkedPoints++;}}
 }if(included)result.games++;}
 result.attempts=result.over+result.under;result.pointRate=rate(result.points,result.attempts);result.linkedPointRate=rate(result.linkedPoints,result.linked);result.targets=[...targets.values()].sort((a,b)=>b.attempts-a.attempts).map(t=>({...t,share:rate(t.attempts,result.linked),pointRate:rate(t.points,t.outcomeTrials)}));return result;
}
export function settingAnalysisPage(content,db){const names=new Map(db.players.map(p=>[p.id,p]));for(const g of db.games)for(const p of g.roster)if(!names.has(p.playerId))names.set(p.playerId,{...p,id:p.playerId});const people=[...names.values()].filter(p=>!p.deletedAt||db.games.some(g=>g.roster.some(x=>x.playerId===p.id))).sort((a,b)=>(b.position==='S')-(a.position==='S'));
 content.innerHTML='<div class="page-heading"><div><h1>세팅 분석</h1><p>세터의 공격수 배분과 연결 시도 대비 득점을 확인합니다.</p></div></div><div class="filters"><label>기간 <select id="settingPeriod"><option value="all">전체</option><option value="year">올해</option><option value="recent">최근 10경기</option></select></label><label>세터 <select id="settingSetter"></select></label><label>경기 <select id="settingGame"></select></label></div><div id="settingReport"></div>';
 const selector=content.querySelector('#settingSetter');selector.innerHTML=people.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.position)}</option>`).join('');
 const updateGames=()=>{const games=filterGames(db.games,content.querySelector('#settingPeriod').value);content.querySelector('#settingGame').innerHTML='<option value="all">전체 경기</option>'+games.map(g=>`<option value="${g.id}">${esc(g.date+' · '+g.opponent+' · '+g.competition)}</option>`).join('');render();};
 const render=()=>{let games=filterGames(db.games,content.querySelector('#settingPeriod').value);const gameId=content.querySelector('#settingGame').value;if(gameId!=='all')games=games.filter(g=>g.id===gameId);if(!selector.value){content.querySelector('#settingReport').innerHTML='<div class="empty">선수를 등록하고 경기 기록을 입력하세요.</div>';return;}const s=setterStats(games,selector.value);
 content.querySelector('#settingReport').innerHTML=`<div class="summary"><div><small>세팅 시도 · 오버 + 언더</small><strong>${s.attempts}</strong></div><div><small>연결 득점</small><strong>${s.points}</strong></div><div><small>시도 대비 득점률</small><strong>${pct(s.pointRate)}</strong></div><div><small>공격수 추적 연결</small><strong>${s.linked}<span>회</span></strong></div></div><p class="muted small">종료 경기 기준 · 기록이 있는 ${s.games}경기 / ${s.sets}세트. 시도 대비 득점률 = 이단연결 득점 ÷ (오버 + 언더). 공격수별 배분율 = 해당 공격수 연결 횟수 ÷ 전체 추적 연결 횟수.</p><section class="panel"><div class="panel-heading"><h2>공격수별 배분</h2><span class="muted small">배분율 기준: 공격수 선택 기록</span></div>${s.targets.length?`<div class="table-wrap"><table><thead><tr><th>공격수</th><th>연결 시도</th><th>배분율</th><th>결과 추적 연결</th><th>결과 추적 득점</th><th>결과 추적 득점률</th></tr></thead><tbody>${s.targets.map(t=>`<tr><td>${esc(t.name)}</td><td>${t.attempts}</td><td>${pct(t.share)}</td><td>${t.outcomeTrials}</td><td>${t.outcomeTrials?t.points:'−'}</td><td>${pct(t.pointRate)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">공격수 선택으로 기록한 연결이 없습니다. 기록표의 이단연결 유형(오버·언더) 칸에서 공격수를 선택하세요.</div>'}</section><p class="muted small">공격수 미추적 기록 ${s.untracked}회는 배분율에서 제외됩니다. 유형에서 선택한 공격수는 배분율에 반영됩니다. 유형 선택만으로 공격 결과를 알 수 없으므로 공격수별 결과 추적 득점률은 과거 공격가능 선택 기록에만 표시합니다. 전체 세터 득점률은 기존 득점 기록으로 계산합니다. 직접 숫자 수정으로 추적이 해제된 기록도 미추적으로 표시합니다.</p><section class="panel"><div class="panel-heading"><h2>세팅 기록</h2></div><div class="table-wrap"><table><thead><tr><th>오버</th><th>언더</th><th>공격가능 성공</th><th>공격가능 득점</th><th>공격가능 실패</th><th>공격불가</th></tr></thead><tbody><tr>${[s.over,s.under,s.success,s.points,s.fail,s.unplayable].map(v=>`<td>${v}</td>`).join('')}</tr></tbody></table></div></section>${s.points>s.attempts?'<p class="error">득점 기록이 유형 시도보다 많습니다. 오버·언더 시도 입력을 확인하세요.</p>':''}`;};selector.onchange=render;content.querySelector('#settingGame').onchange=render;content.querySelector('#settingPeriod').onchange=updateGames;updateGames();}
